// Pull the first customer message out of Meta's webhook payload.
// Status updates (sent/delivered/read) have no "messages" → stop here.
const body = $json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value || {};
const msg = value.messages?.[0];
if (!msg) return [];

const contact = value.contacts?.[0] || {};
const type = msg.type;
let text = '';
let mediaId = '';
let caption = '';

if (type === 'text') text = msg.text?.body || '';
else if (type === 'image') { mediaId = msg.image?.id || ''; caption = msg.image?.caption || ''; }
else if (type === 'button') text = msg.button?.text || '';
else if (type === 'interactive') text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';

const kind = (type === 'image') ? 'image' : (text ? 'text' : 'unsupported');

return [{ json: {
  phone: msg.from,                       // e.g. 8801XXXXXXXXX
  phonePlus: '+' + msg.from,
  name: contact.profile?.name || '',
  messageId: msg.id,
  waType: type,
  kind,
  text: text.slice(0, 4000),
  mediaId,
  caption,
  timestamp: new Date(Number(msg.timestamp) * 1000).toISOString(),
}}];

