// Catalog is only sent when the customer's own message asks for pictures/catalog.
// Turn the agent's JSON answer into fields. If the model ever returns plain text, send it as the reply.
const raw = String($json.output ?? '').trim();
let data = null;
try {
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = cleaned.indexOf('{'), end = cleaned.lastIndexOf('}');
  data = JSON.parse(start >= 0 ? cleaned.slice(start, end + 1) : cleaned);
} catch (e) { data = null; }

const msg = $('Extract Message').item.json;
const validCats = ['all', 'Adult Male', 'Adult Female', 'Kids Boy', 'Kids Girl'];
let reply = (data && typeof data.reply === 'string' && data.reply.trim())
  ? data.reply.trim()
  : (raw || 'Thank you for your message! Could you please tell me a little more about what you are looking for?');

// Never close an order before the customer's details are collected.
const REQUIRED = [['customer_name', 'Your name'], ['business_name', 'Shop / business name'], ['business_type', 'Business type (shop, wholesaler, online seller…)'],
  ['city', 'City'], ['delivery_address', 'Full delivery address'], ['payment_preference', 'Payment method (Bank transfer, bKash, Nagad or Cash at factory)'],
  ['required_by', 'Required delivery date']];
let lead = (data && data.lead && typeof data.lead === 'object') ? data.lead : null;
if (lead && String(lead.order_items || '').trim()) {
  const missing = REQUIRED.filter(([k]) => !String(lead[k] ?? '').trim());
  const closing = /sales (team|representative|rep)|invoice|will contact you/i.test(reply) || /Qualified|Handed Over/.test(lead.lead_status || '');
  if (missing.length && closing) {
    if (!/please (share|provide)|following details|your name|shop ?\/ ?business name/i.test(reply)) reply += '\n\nTo prepare your invoice, please share:\n' + missing.map((m, i) => (i + 1) + '. ' + m[1]).join('\n');
    if (/Qualified/.test(lead.lead_status || '')) { lead.lead_status = 'Collecting Details'; lead.lead_score = Math.min(Number(lead.lead_score) || 4, 4); }
  }
}

return [{ json: {
  phone: msg.phone,
  phonePlus: msg.phonePlus,
  whatsappName: msg.name,
  reply: reply.slice(0, 4000),
  action: (data?.action === 'send_catalog' && /\b(send|show|share|see|view|look at|check out|browse|display)\b[\s\S]*\b(catalog|catalogue|pictures?|photos?|images?|pics?|designs?|collection|products?|items?|samples?|jeans)\b|\b(catalog|catalogue)\b/i.test(msg.text || '')) ? 'send_catalog' : 'none',
  catalogCategory: validCats.includes(data?.catalog_category) ? data.catalog_category : 'all',
  lead,
  parsedOk: !!data,
}}];

// Map the agent's lead object to the Airtable "Leads" fields (exact column names).
// The lead is found by 'Lead ID' (WA-<phone>) and then updated, or created if new.
const p = $json; const L = p.lead || {};
const STATUSES = ['New','Browsing Catalog','Negotiating','Collecting Details','Qualified – Ready for Sales','Handed Over','Retail-Declined','Not Interested'];
const txt = v => (v === undefined || v === null) ? '' : String(v).trim();
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.]/g, '')); return Number.isFinite(n) ? n : 0; };

const leadId = 'WA-' + p.phone;
const fields = {
  'Lead ID': leadId,
  'WhatsApp Number': p.phonePlus,
  'Last Contact': new Date().toISOString(),
};
const put = (k, v) => { if (v !== '' && v !== 0 && v !== null && v !== undefined) fields[k] = v; };

put('Customer Name', txt(L.customer_name) || txt(p.whatsappName));
put('Business Name', txt(L.business_name));
const BT = ['Retailer (shop)','Wholesaler','Online Seller','Boutique','Distributor','Other'];
const bt = txt(L.business_type);
put('Business Type', BT.find(o => o.toLowerCase() === bt.toLowerCase())
  || (/retail|shop|store/i.test(bt) ? 'Retailer (shop)' : /wholesal/i.test(bt) ? 'Wholesaler'
  : /online|facebook|f-commerce|e-?commerce/i.test(bt) ? 'Online Seller' : /boutique/i.test(bt) ? 'Boutique'
  : /distribut/i.test(bt) ? 'Distributor' : bt ? 'Other' : ''));
put('Country', txt(L.country) || 'Bangladesh');
put('City', txt(L.city));
put('Interested Product IDs', txt(L.interested_product_ids));
put('Order Items (ID × bundles @ agreed price)', txt(L.order_items));
put('Total Bundles', num(L.total_bundles));
put('Estimated Order Value (TK)', num(L.estimated_order_value));
put('Payment Preference', txt(L.payment_preference));
put('Delivery Address', txt(L.delivery_address));
if (/^\d{4}-\d{2}-\d{2}$/.test(txt(L.required_by))) fields['Required By'] = txt(L.required_by);
if (STATUSES.includes(txt(L.lead_status))) fields['Lead Status'] = txt(L.lead_status);
const score = Math.round(num(L.lead_score)); if (score >= 1 && score <= 5) fields['Lead Score (1–5)'] = score;
if (L.retail_request === true || L.retail_request === 'true') fields['Retail Request?'] = true;
put('Conversation Summary', txt(L.conversation_summary));

return [{ json: { leadId, fields } }];

// Merge the new lead data with the record already in Airtable:
// keep every product the customer asked about, never downgrade a qualified lead, keep the highest score.
const rec = $json.records[0];
const old = rec.fields || {};
const f = { ...$('Build Airtable Fields').item.json.fields };
const ids = s => String(s || '').split(/[,;\s]+/).map(x => x.trim().toUpperCase()).filter(Boolean);
const all = [...new Set([...ids(old['Interested Product IDs']), ...ids(f['Interested Product IDs'])])];
if (all.length) f['Interested Product IDs'] = all.join(', ');
const rank = { 'New': 1, 'Browsing Catalog': 2, 'Negotiating': 3, 'Collecting Details': 3, 'Qualified – Ready for Sales': 4, 'Handed Over': 5 };
const o = old['Lead Status'], n = f['Lead Status'];
if (n && rank[n] && rank[o] && rank[n] < rank[o]) f['Lead Status'] = o;          // no downgrade
const os = Number(old['Lead Score (1–5)'] || 0), ns = Number(f['Lead Score (1–5)'] || 0);
if (os > ns) f['Lead Score (1–5)'] = os;
if (old['Retail Request?'] === true) delete f['Retail Request?'];
if (['Qualified – Ready for Sales', 'Handed Over'].includes(f['Lead Status'])) f['Retail Request?'] = false;  // a qualified wholesale lead is no longer a retail request
return [{ json: { id: rec.id, fields: f } }];
